SELECT complaint_id
FROM {{ ref('complaint_metrics') }}
WHERE complaint_count <> 1 OR timely_response_count NOT IN (0, 1) OR not_timely_response_count NOT IN (0, 1) OR known_timeliness_count NOT IN (0, 1) OR unknown_timeliness_count NOT IN (0, 1) OR narrative_count NOT IN (0, 1) OR closed_with_explanation_count NOT IN (0, 1) OR monetary_relief_count NOT IN (0, 1) OR non_monetary_relief_count NOT IN (0, 1) OR in_progress_count NOT IN (0, 1) OR untimely_response_outcome_count NOT IN (0, 1) OR unknown_response_outcome_count NOT IN (0, 1) OR public_response_available_count NOT IN (0, 1) OR missing_state_count NOT IN (0, 1) OR missing_zip_count NOT IN (0, 1) OR missing_issue_count NOT IN (0, 1) OR missing_sub_issue_count NOT IN (0, 1) OR sent_before_received_count NOT IN (0, 1)
